"""Publish all frozen controls and first-run outcomes as a local, auditable HTML report."""
import collections, hashlib, html, json, shutil, statistics
from pathlib import Path
from PIL import Image, ImageOps
ROOT=Path('evaluation/inputs/unseen-single-2026-11-03');OUT=Path('evaluation/private/unseen-single-2026-11-03');SITE=Path('site/unseen-validation')
def main():
 manifest=json.loads((OUT/'manifest.json').read_text());result=json.loads((OUT/'results.json').read_text());rows=result['rows'];cases={c['id']:c for c in manifest['cases']}
 assert len(rows)==len(cases)==15 and len({r['id'] for r in rows})==15
 assert result['manifest_sha256']==hashlib.sha256((OUT/'manifest.json').read_bytes()).hexdigest()
 SITE.mkdir(exist_ok=True);(SITE/'img').mkdir(exist_ok=True)
 for src in json.loads((ROOT/'downloaded.json').read_text()):
  with Image.open(src['path']) as raw:
   im=ImageOps.exif_transpose(raw).convert('RGB');im.thumbnail((1200,1200));im.save(SITE/'img'/f"scd-{src['id']}.jpg",quality=88)
 for c in cases.values():
  with Image.open(c['files']['note']['path']) as im:
   im.thumbnail((1000,700));im.save(SITE/'img'/(c['id']+'-note.png'))
 for variant in ['baseline','receiver_uncertain']:
  shutil.copyfile(cases['scd-37-'+variant]['files']['audio']['path'],SITE/(variant+'.wav'))
 # Public manifest keeps reproducibility hashes and file names, without machine-specific paths.
 public=json.loads(json.dumps(manifest))
 for c in public['cases']:
  for info in c['files'].values():info['filename']=Path(info.pop('path')).name
 counts=collections.Counter(r['action'] for r in rows)
 positives=[r for r in rows if r['expected_action']=='post'];negatives=[r for r in rows if r['expected_action']!='post'];human=[r for r in rows if r['expected_action']=='human']
 summary={'photos':5,'controls':len(rows),'actions':dict(counts),'exact_targets_met':sum(r['exact_target_met'] for r in rows),'acceptable_actions_met':sum(r['acceptable_action_met'] for r in rows),'acceptance_targets':len(positives),'accepted_positive_targets':sum(r['action']=='post' for r in positives),'nonpost_targets':len(negatives),'posts_on_nonpost_targets':sum(r['action']=='post' for r in negatives),'human_targets':len(human),'human_targets_routed_to_human':sum(r['action']=='human' for r in human),'technical_failures':counts['error'],'median_seconds_all_attempts':round(statistics.median(r['seconds'] for r in rows),1),'total_cost_usd':None,'erp_writes':sum(r.get('evidence',{}).get('erp_written',False) for r in rows)}
 payload={'summary':summary,'manifest':public,'manifest_sha256':result['manifest_sha256'],'rows':rows}
 (SITE/'results.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2));Path('evaluation/unseen-controls-2026-11-03.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2))
 esc=lambda s:html.escape(str(s));label={'post':'Kabul','block':'Ret','human':'İnsan incelemesi','error':'Teknik hata'}
 table=[];details=[]
 for r in rows:
  c=cases[r['id']];e=r.get('evidence',{});reason=' '.join(e.get('decision',{}).get('reasons',[])) or r.get('error_type','');partial=r.get('partial',{})
  table.append(f"<tr><td>{c['source_image_id']}</td><td>{esc(c['scenario'])}</td><td>{label[c['expected_action']]}</td><td class='{r['action']}'>{label[r['action']]}</td><td>{esc(r.get('rule',partial.get('failed_step','—')))}</td><td>{r['seconds']:.1f} sn</td><td>{'✓' if r['exact_target_met'] else '✗'}</td></tr>")
  details.append(f"<details><summary>{esc(r['id'])} — {label[r['action']]}</summary><p><strong>Önceden belirlenen gerekçe:</strong> {esc(c['reference_rationale'])}</p><p><strong>Kayıtlı karar:</strong> {esc(reason)}</p><p>İkinci okuyucu ve denetim: {'kayıtta mevcut' if e.get('second_opinions') else 'bu sonuçta tamamlandığı gösterilmedi'}.</p><p><a href='img/{esc(r['id'])}-note.png'>Hazırlanmış belgeyi aç</a></p><pre>{esc(json.dumps(r,ensure_ascii=False,indent=2))}</pre></details>")
 photos=''.join(f"<figure><a href='img/scd-{i}.jpg'><img src='img/scd-{i}.jpg' alt='SCD {i} seçilmiş kaynak fotoğrafının küçültülmüş önizlemesi' loading='lazy'></a><figcaption>SCD {i} · {esc(cases[f'scd-{i}-baseline']['order']['product'])}</figcaption></figure>" for i in [37,93,111,278,711])
 page='''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yeni fotoğraf testleri · Count Before You Post</title><style>body{font:16px/1.6 system-ui;background:#f5f4ee;color:#17313e;margin:0}main{max-width:1150px;margin:auto;padding:36px 22px}h1{font-size:clamp(28px,4vw,44px);line-height:1.15}a{color:#175bdb}.notice{background:#e7eef9;padding:20px;border-left:4px solid #175bdb}.photos{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}figure{margin:0;background:white;padding:12px;border-radius:10px}img{width:100%;height:190px;object-fit:contain}figcaption{font-size:13px}table{width:100%;border-collapse:collapse;background:white;font-size:14px}th,td{padding:12px;text-align:left;border-bottom:1px solid #d6dfdf}.scroll{overflow:auto}.post{color:#17673f;font-weight:bold}.block,.error{color:#b42b38;font-weight:bold}.human{color:#8c5a00;font-weight:bold}details{border-top:1px solid #ccd6da;padding:16px 0}summary{cursor:pointer;font-weight:700}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 monospace;background:#e9eef0;padding:16px;max-height:430px;overflow:auto}.small{font-size:13px}</style><main><a href="../jury/">← Jüri demosu</a><h1>5 yeni fotoğraf.<br>15 önceden sabitlenmiş kontrol.</h1><p>3 Kasım 2026 · İlk uygulama koşularının tamamı</p>'''
 page+=f"<div class='notice'><strong>{counts['post']} kabul · {counts['block']} ret · {counts['human']} insan incelemesi · {counts['error']} teknik hata.</strong><p>Kesin karar hedefi: {summary['exact_targets_met']}/15. Kabul hedefi: {summary['accepted_positive_targets']}/{len(positives)}. Otomatik kayıt yapılmaması gereken {len(negatives)} kontrolde {summary['posts_on_nonpost_targets']} kabul.</p><p>ERP yazımı: {summary['erp_writes']}. Tüm denemelerde medyan süre: {summary['median_seconds_all_attempts']} sn. Maliyet ölçülmedi.</p></div>"
 page+='<h2>Başarı kadar önemli iki bulgu</h2><p><strong>111 numaralı yeni fotoğrafta üç karar doğru:</strong> temel belge kabul, miktar uyuşmazlığı ret, kararsız ses insan incelemesi. Kabulde ikinci okuyucu ve denetim tamamlandı. Bu, tek yeni fotoğrafta ürün-adı profili için entegrasyon kanıtıdır; genellenebilir başarı oranı değildir.</p><p><strong>711 numaralı fotoğrafta beklenmeyen kabul:</strong> kadraj/örtülme nedeniyle önceden insan incelemesi hedeflediğimiz temel kontrol kabul edildi. Kamera “tüm koliler görünür” dedi; bu görsel varsayım ile önceden belirlenmiş hedef uyuşmuyor. Etiketlerin tamamının tanımlanmadığı da kayıtta mevcut; ürün-adı profili bunu kesin kimlik profili gibi engellemiyor. Gerçek yanlış stok kaydı kanıtı yok, fakat bu hedefe göre incelemeye gitmesi gereken bir otomatik onay var.</p><p><strong>711 üzerinde iki OCR kaynaklı ret:</strong> miktar kontrolünde 苦 karakteri 苫, kararsız ses kontrolünde 苔 olarak okundu. “not_ordered” kuralı diğer kontrollere ulaşmadan ret verdi. Bu retleri miktar veya ses kusurunu doğru yakalama olarak saymıyoruz. 37 numaralı miktar kontrolü ise insan incelemesi hedefi yerine miktar uyuşmazlığı nedeniyle ret verdi; güvenli bir duruş, ancak aynı karar değil.</p><p><strong>Yorum:</strong> 2 kabulün yalnızca 1’i önceden temiz kabul hedefidir. 13/15 geniş kabul edilebilir karar ölçütü, 11/15 kesin hedef eşleşmesinden farklıdır ve %87 saha doğruluğu anlamına gelmez. 14 otomatik onay verilmemesi gereken kontrolden 1’inde onay çıktı. Sonuçlar yeni denemeyle düzeltilmedi veya elenmedi.</p>'
 page+='<h2>Kapsam ve yorumlama</h2><p>Bu test, mevcut <strong>ürün adı eşleştirme</strong> akışını kullanır; güvenilir referans kodları bulunmadığından siparişlerde marka/model/SKU kimliği yoktur. Önceki Deli ürün kodu kontrolüne eşdeğer değildir. Model istemleri, karar kuralları ve eşikleri değiştirilmedi. Tedarikçi, görsel eşleştirme, teslim alan sesi, kabul öncesi ikinci okuyucu ve denetim akışı açık kaldı.</p><p>Eski 30 test fotoğrafı ve sekiz görsel eleme adayı dışlandı. Kalan tek koli anotasyonlu beş fotoğrafın tamamı, model sonuçları görülmeden seçildi. Çalışma zamanı görsel ön taramasıyla fotoğraf elenmedi. Ancak tek koli seçimi kolaylık sağlayan dar bir alt kümedir; fotoğrafların model eğitiminde bulunmadığı bilinmiyor.</p><p>111 numaralı fotoğraf temiz kabul adayıdır. 37, 93, 278 ve 711 görüntülerinde kadraj/örtülme veya hasar nedeniyle önceden insan incelemesi hedeflendi. Bu hedefler asistanın çağrı öncesi görsel incelemesidir; bağımsız saha doğrusu değildir. Dolayısıyla bu deneyde yalnızca <strong>bir temiz kabul hedefi</strong> vardır.</p><p>Her fotoğraf için temel belge, miktarı 2 koliye çıkarılmış belge/sipariş ve kararsız teslim alan sesi üretildi. Gerçek teslimat belgeleri veya çalışan kayıtları değildir. Miktar kusurunda güvenli sonuç hem ret hem insan incelemesi olabilir; tabloda daha dar kesin hedef de gösterilir. Daha erken bir kural, miktar veya ses kusurunun değerlendirilmesini engelleyebilir. Yalnızca “kayıt yapılmadı” sonucu, ilgili kusurun yakalandığını kanıtlamaz.</p><p>Her kontrol tek uygulama koşusu: sonuç sonrası düzeltme veya yeniden deneme yok. Mevcut SDK aktarım tekrarları etkin kaldı. Teknik hatalar başarı sayılmadı. Fotoğraflar kırpılmadan modele gönderildi; aşağıdakiler yalnızca küçültülmüş önizlemeler. İnsan süresi, iş yükü tasarrufu ve gerçek ERP entegrasyonu ölçülmedi.</p>'
 page+='<h2>Seçilen fotoğrafların tamamı</h2><div class="photos">'+photos+'</div><p class="small">Fotoğraflar: Jinrong Yang ve diğerleri, <a href="https://github.com/yancie-yjr/scd.github.io">SCD / LSCD</a>. Kaynaklar ve yeniden boyutlandırılmış önizlemeler <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/">CC BY-NC-SA 4.0</a>.</p>'
 page+='<h2>Sentetik ses girdileri</h2><p>Aynı iki ses dosyası tüm fotoğraflarda kullanıldı; bunlar bağımsız çalışan kayıtları değildir.</p><p>Kesin sayım:</p><audio controls preload="none" src="baseline.wav"></audio><p>Kararsız sayım:</p><audio controls preload="none" src="receiver_uncertain.wav"></audio><h2>15 sonucun tamamı</h2><div class="scroll"><table><thead><tr><th>Fotoğraf</th><th>Kontrol</th><th>Önceden hedef</th><th>Gerçek karar</th><th>Karar kuralı / hata adımı</th><th>Süre</th><th>Kesin hedef</th></tr></thead><tbody>'+''.join(table)+'</tbody></table></div><h2>Kanıt ve hata kayıtları</h2><p><a href="results.json" download>Tüm sonuçları, seçim protokolünü ve girdi özetlerini indir (JSON)</a></p><p class="small">Donmuş manifest SHA-256: '+esc(result['manifest_sha256'])+'</p>'+''.join(details)+'</main></html>'
 (SITE/'index.html').write_text(page)
 print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
